/* BattleQuiz - Technology.
 * Each entry carries both languages; `c` is the index of the correct option
 * in BOTH arrays, and `d` is the difficulty level 1-8.
 */
window.BANK = window.BANK || [];
window.BANK.push(
  { id:"tec001", t:"tech", d:1, c:0, en:{q:"What do you use to type letters on a computer?",a:["A keyboard","A window","A lamp","A plate"]}, tr:{q:"Bilgisayarda harf yazmak için ne kullanırsın?",a:["Klavye","Pencere","Lamba","Tabak"]}, ex:{en:"A keyboard has a key for every letter, so pressing them types words onto the screen.",tr:"Klavyede her harf için bir tuş vardır, bu tuşlara basmak ekrana kelime yazdırır."} },
  { id:"tec002", t:"tech", d:1, c:0, en:{q:"What do you call the small device you move to point on a screen?",a:["A mouse","A rat","A cat","A bird"]}, tr:{q:"Ekranda imleci hareket ettirdiğin küçük araca ne denir?",a:["Fare","Sıçan","Kedi","Kuş"]}, ex:{en:"Moving a computer mouse slides an arrow, called a cursor, around the screen.",tr:"Bilgisayar faresini hareket ettirmek, ekrandaki imleç adı verilen oku kaydırır."} },
  { id:"tec003", t:"tech", d:1, c:0, en:{q:"Which machine in the kitchen keeps food cold?",a:["The fridge","The oven","The toaster","The kettle"]}, tr:{q:"Mutfakta yiyecekleri soğuk tutan makine hangisidir?",a:["Buzdolabı","Fırın","Ekmek kızartma makinesi","Su ısıtıcısı"]}, ex:{en:"A fridge uses a cooling system to keep the air inside cold, slowing down food spoiling.",tr:"Buzdolabı, içindeki havayı soğuk tutmak için bir soğutma sistemi kullanır ve bu, yiyeceğin bozulmasını yavaşlatır."} },
  { id:"tec004", t:"tech", d:1, c:0, en:{q:"Which of these tells you what time it is?",a:["A clock","A mirror","A window","A shoe"]}, tr:{q:"Bunlardan hangisi sana saatin kaç olduğunu söyler?",a:["Duvar saati","Ayna","Pencere","Ayakkabı"]}, ex:{en:"A clock shows the time using moving hands or digital numbers.",tr:"Saat, hareketli kolları ya da dijital rakamlarıyla zamanı gösterir."} },
  { id:"tec005", t:"tech", d:1, c:0, en:{q:"How many wheels does a bicycle have?",a:["Two","Three","Four","One"]}, tr:{q:"Bir bisikletin kaç tekerleği vardır?",a:["İki","Üç","Dört","Bir"]}, ex:{en:"A bicycle rolls on two wheels, one at the front and one at the back.",tr:"Bisiklet, önde ve arkada olmak üzere iki tekerlek üzerinde ilerler."} },
  { id:"tec006", t:"tech", d:1, c:0, en:{q:"What do you wear on your ears to listen to music?",a:["Headphones","Gloves","Socks","Glasses"]}, tr:{q:"Müzik dinlemek için kulaklarına ne takarsın?",a:["Kulaklık","Eldiven","Çorap","Gözlük"]}, ex:{en:"Headphones sit over or in your ears, sending sound straight to you without a speaker.",tr:"Kulaklıklar kulaklarının üzerine veya içine oturur ve sesi hoparlör olmadan doğrudan sana iletir."} },
  { id:"tec007", t:"tech", d:1, c:0, en:{q:"Which machine puts words from a computer onto paper?",a:["A printer","A fridge","A radio","A fan"]}, tr:{q:"Bilgisayardaki yazıyı kâğıda basan makine hangisidir?",a:["Yazıcı","Buzdolabı","Radyo","Vantilatör"]}, ex:{en:"A printer transfers digital text and images from a computer onto physical paper.",tr:"Yazıcı, bilgisayardaki dijital metin ve görselleri gerçek kâğıda aktarır."} },
  { id:"tec008", t:"tech", d:1, c:0, en:{q:"Which machine carries people through the sky?",a:["An aeroplane","A bus","A boat","A bicycle"]}, tr:{q:"İnsanları gökyüzünde taşıyan araç hangisidir?",a:["Uçak","Otobüs","Gemi","Bisiklet"]}, ex:{en:"An aeroplane's engines and wings let it fly through the air over long distances.",tr:"Uçağın motorları ve kanatları, havada uzun mesafeler kat etmesini sağlar."} },
  { id:"tec009", t:"tech", d:1, c:0, en:{q:"In a tall building, what takes you up without climbing the stairs?",a:["An elevator","A door","A window","A chair"]}, tr:{q:"Yüksek bir binada merdiven çıkmadan seni yukarı ne taşır?",a:["Asansör","Kapı","Pencere","Sandalye"]}, ex:{en:"An elevator is a small moving room that carries people up and down inside a building.",tr:"Asansör, bir binanın içinde insanları yukarı ve aşağı taşıyan hareketli küçük bir odadır."} },
  { id:"tec010", t:"tech", d:1, c:0, en:{q:"Which machine at home do you watch cartoons on?",a:["A television","A fridge","A washing machine","A kettle"]}, tr:{q:"Evde çizgi filmleri hangi makinede izlersin?",a:["Televizyon","Buzdolabı","Çamaşır makinesi","Su ısıtıcısı"]}, ex:{en:"A television receives broadcast or streamed signals and displays them as moving pictures.",tr:"Televizyon, yayın veya akış sinyallerini alır ve bunları hareketli görüntü olarak gösterir."} },
  { id:"tec011", t:"tech", d:1, k:"tf", v:false, en:{q:"A washing machine is used to wash dirty dishes."}, tr:{q:"Çamaşır makinesi kirli bulaşıkları yıkamak için kullanılır."}, ex:{en:"A washing machine cleans clothes; a dishwasher is the appliance built for washing dishes.",tr:"Çamaşır makinesi kıyafetleri yıkar; bulaşık yıkamak için yapılmış cihaza ise bulaşık makinesi denir."} },
  { id:"tec012", t:"tech", d:1, k:"tf", v:true, en:{q:"A flashlight makes light so you can see in the dark."}, tr:{q:"El feneri, karanlıkta görebilmen için ışık verir."}, ex:{en:"A flashlight uses a small battery-powered bulb or LED to shine light where you point it.",tr:"El feneri, tuttuğun yöne ışık tutmak için pille çalışan küçük bir ampul veya LED kullanır."} },
  { id:"tec013", t:"tech", d:1, k:"tf", v:false, en:{q:"A traffic light shows red, blue and green lights."}, tr:{q:"Trafik ışığında kırmızı, mavi ve yeşil ışıklar yanar."}, ex:{en:"A traffic light cycles between red, yellow (amber) and green, not blue.",tr:"Trafik ışığı mavi değil, kırmızı, sarı ve yeşil arasında sırayla değişir."} },
  { id:"tec014", t:"tech", d:1, k:"tf", v:true, en:{q:"A telephone lets you talk to someone who is far away."}, tr:{q:"Telefon, uzaktaki biriyle konuşmanı sağlar."}, ex:{en:"A telephone carries your voice as a signal to another phone, however far away it is.",tr:"Telefon, ne kadar uzakta olursa olsun sesini bir sinyal olarak başka bir telefona taşır."} },
  { id:"tec015", t:"tech", d:1, k:"tf", v:false, en:{q:"A helicopter needs a long runway to take off."}, tr:{q:"Helikopterin havalanmak için uzun bir piste ihtiyacı vardır."}, ex:{en:"A helicopter's spinning rotor lets it lift straight up, so it needs no runway at all.",tr:"Helikopterin dönen pervanesi dikey olarak yükselmesini sağlar, bu yüzden hiç piste ihtiyacı yoktur."} },
  { id:"tec016", t:"tech", d:1, k:"tf", v:true, en:{q:"A laptop has a battery, so it can work without being plugged in."}, tr:{q:"Dizüstü bilgisayarın pili vardır, bu yüzden prize takılı olmadan da çalışabilir."}, ex:{en:"A laptop's built-in battery stores power, letting it run for a while away from a wall socket.",tr:"Dizüstü bilgisayarın dahili pili enerji depolar, böylece prizden uzakta bir süre çalışabilir."} },
  { id:"tec017", t:"tech", d:2, c:0, en:{q:"Which part is often called the brain of a computer?",a:["The processor","The screen","The keyboard","The speaker"]}, tr:{q:"Bilgisayarın beyni sayılan parça hangisidir?",a:["İşlemci","Ekran","Klavye","Hoparlör"]}, ex:{en:"The processor carries out a computer's calculations and instructions, much like a brain directs a body.",tr:"İşlemci, tıpkı bir beynin vücudu yönetmesi gibi, bilgisayarın hesaplamalarını ve komutlarını yürütür."} },
  { id:"tec018", t:"tech", d:2, c:0, en:{q:"What does a solar panel turn sunlight into?",a:["Electricity","Water","Sound","Paper"]}, tr:{q:"Güneş paneli güneş ışığını neye çevirir?",a:["Elektrik","Su","Ses","Kâğıt"]}, ex:{en:"Solar panels contain cells that convert sunlight directly into electrical energy.",tr:"Güneş panelleri, güneş ışığını doğrudan elektrik enerjisine çeviren hücreler içerir."} },
  { id:"tec019", t:"tech", d:2, c:0, en:{q:"What does a printer do?",a:["Puts words and pictures on paper","Cools your food","Cleans the floor","Tells you the time"]}, tr:{q:"Bir yazıcı ne yapar?",a:["Yazı ve resimleri kâğıda basar","Yiyecekleri soğutur","Yerleri temizler","Saati söyler"]}, ex:{en:"A printer takes a digital file and reproduces its text and images on physical paper.",tr:"Yazıcı, dijital bir dosyayı alır ve metnini ile görsellerini fiziksel kâğıda basar."} },
  { id:"tec020", t:"tech", d:2, c:0, en:{q:"Which device lets you listen to music without other people hearing it?",a:["Headphones","A loudspeaker","A torch","A calculator"]}, tr:{q:"Başkaları duymadan müzik dinlemeni hangi araç sağlar?",a:["Kulaklık","Hoparlör","El feneri","Hesap makinesi"]}, ex:{en:"Headphones direct sound only to your own ears, keeping the music private from others nearby.",tr:"Kulaklıklar sesi sadece kendi kulaklarına yönlendirir, böylece müzik yakındakilere duyulmaz."} },
  { id:"tec021", t:"tech", d:2, c:0, en:{q:"Which device is made for taking photographs?",a:["A camera","A kettle","A hammer","A broom"]}, tr:{q:"Fotoğraf çekmek için yapılmış araç hangisidir?",a:["Fotoğraf makinesi","Su ısıtıcısı","Çekiç","Süpürge"]}, ex:{en:"A camera captures light through a lens and records it as a still photograph.",tr:"Fotoğraf makinesi, bir mercekten geçen ışığı yakalayıp durağan bir fotoğraf olarak kaydeder."} },
  { id:"tec022", t:"tech", d:2, c:0, en:{q:"What do we call a machine built to do jobs on its own?",a:["A robot","A poster","A blanket","A ladder"]}, tr:{q:"İşleri kendi başına yapmak için üretilen makineye ne denir?",a:["Robot","Afiş","Battaniye","Merdiven"]}, ex:{en:"A robot is a machine programmed to sense its surroundings and perform tasks automatically.",tr:"Robot, çevresini algılayıp görevleri otomatik olarak yerine getirecek şekilde programlanmış bir makinedir."} },
  { id:"tec023", t:"tech", d:2, c:0, en:{q:"What do we call a written message sent over the internet?",a:["An email","A postcard","A newspaper","A parcel"]}, tr:{q:"İnternet üzerinden gönderilen yazılı mesaja ne denir?",a:["E-posta","Kartpostal","Gazete","Koli"]}, ex:{en:"Email lets you send written messages instantly to anyone over the internet.",tr:"E-posta, internet üzerinden herhangi birine anında yazılı mesaj göndermeni sağlar."} },
  { id:"tec024", t:"tech", d:2, c:0, en:{q:"What do you put inside a TV remote control to make it work?",a:["Batteries","Water","Sand","Paper"]}, tr:{q:"Televizyon kumandasının çalışması için içine ne konur?",a:["Pil","Su","Kum","Kâğıt"]}, ex:{en:"Batteries supply the small electric current a remote control needs to send its signal.",tr:"Piller, kumandanın sinyalini göndermesi için gereken küçük elektrik akımını sağlar."} },
  { id:"tec025", t:"tech", d:2, c:0, en:{q:"What is a wireless internet connection in a home usually called?",a:["Wi-Fi","DVD","PDF","MP3"]}, tr:{q:"Evdeki kablosuz internet bağlantısına genellikle ne ad verilir?",a:["Wi-Fi","DVD","PDF","MP3"]}, ex:{en:"Wi-Fi lets devices connect to the internet through radio signals instead of a cable.",tr:"Wi-Fi, cihazların bir kabloya gerek kalmadan radyo sinyalleriyle internete bağlanmasını sağlar."} },
  { id:"tec026", t:"tech", d:2, c:0, en:{q:"What do you use so that only you can open your own account?",a:["A password","A sticker","A photo","A song"]}, tr:{q:"Hesabını yalnızca senin açabilmen için ne kullanırsın?",a:["Şifre","Çıkartma","Fotoğraf","Şarkı"]}, ex:{en:"A password is a secret code that proves it is really you trying to open your account.",tr:"Şifre, hesabını açmaya çalışanın gerçekten sen olduğunu kanıtlayan gizli bir koddur."} },
  { id:"tec027", t:"tech", d:2, c:0, en:{q:"Which instrument is used to look at faraway stars and planets?",a:["A telescope","A microscope","A thermometer","A pair of scales"]}, tr:{q:"Uzaktaki yıldızlara ve gezegenlere bakmak için hangi alet kullanılır?",a:["Teleskop","Mikroskop","Termometre","Terazi"]}, ex:{en:"A telescope gathers and magnifies distant light, making faraway stars and planets visible up close.",tr:"Teleskop, uzaktaki ışığı toplayıp büyüterek gökteki yıldız ve gezegenleri yakından görünür kılar."} },
  { id:"tec028", t:"tech", d:2, k:"tf", v:true, en:{q:"Rockets are used to carry astronauts and satellites into space."}, tr:{q:"Roketler, astronotları ve uyduları uzaya taşımak için kullanılır."}, ex:{en:"Rockets burn fuel to generate the huge thrust needed to escape Earth's gravity into space.",tr:"Roketler, Dünya'nın çekiminden kurtulup uzaya çıkmak için gereken devasa itmeyi elde etmek üzere yakıt yakar."} },
  { id:"tec029", t:"tech", d:2, k:"tf", v:true, en:{q:"Alexander Graham Bell is famous for inventing the telephone."}, tr:{q:"Alexander Graham Bell, telefonu icat etmesiyle ünlüdür."}, ex:{en:"Alexander Graham Bell was granted the first patent for the telephone in 1876.",tr:"Alexander Graham Bell, 1876'da telefon için ilk patenti aldı."} },
  { id:"tec030", t:"tech", d:2, k:"tf", v:false, en:{q:"An electric car needs petrol to run."}, tr:{q:"Elektrikli bir arabanın çalışmak için benzine ihtiyacı vardır."}, ex:{en:"An electric car runs on power stored in a battery, not on petrol at all.",tr:"Elektrikli araba, hiç benzin kullanmadan bir pilde depolanan güçle çalışır."} },
  { id:"tec031", t:"tech", d:2, k:"tf", v:true, en:{q:"In a video call, two people can see and hear each other at the same time."}, tr:{q:"Görüntülü aramada iki kişi aynı anda birbirini görüp duyabilir."}, ex:{en:"A video call sends both picture and sound both ways at once, so both people see and hear each other live.",tr:"Görüntülü aramada resim ve ses iki yönlü olarak aynı anda gönderilir, böylece iki taraf da birbirini canlı görüp duyar."} },
  { id:"tec032", t:"tech", d:2, k:"tf", v:false, en:{q:"On a computer keyboard, the letters are arranged in alphabetical order from A to Z."}, tr:{q:"Bilgisayar klavyesinde harfler A'dan Z'ye alfabetik sırayla dizilmiştir."}, ex:{en:"Most keyboards use the QWERTY layout, named after its first row of letters, not alphabetical order.",tr:"Çoğu klavye, alfabetik sıra değil, ilk harf sırasından adını alan QWERTY düzenini kullanır."} },
  { id:"tec033", t:"tech", d:3, c:0, en:{q:"Which of these is a programming language?",a:["Python","Photoshop","Windows","Chrome"]}, tr:{q:"Bunlardan hangisi bir programlama dilidir?",a:["Python","Photoshop","Windows","Chrome"]}, ex:{en:"Python is a widely used programming language known for being readable and beginner-friendly.",tr:"Python, okunabilirliği ve yeni başlayanlar için kolaylığıyla bilinen yaygın bir programlama dilidir."} },
  { id:"tec034", t:"tech", d:3, c:0, en:{q:"What does \"www\" stand for?",a:["World Wide Web","Wide World Web","Web World Wide","World Web Wide"]}, tr:{q:"\"www\" neyin kısaltmasıdır?",a:["World Wide Web","Wide World Web","Web World Wide","World Web Wide"]}, ex:{en:"\"www\" stands for World Wide Web, the system of linked pages you browse on the internet.",tr:"\"www\", internette gezdiğin bağlantılı sayfalar sistemi olan World Wide Web'in kısaltmasıdır."} },
  { id:"tec035", t:"tech", d:3, c:0, en:{q:"Who is generally credited with developing the electric light bulb?",a:["Thomas Edison","Isaac Newton","Albert Einstein","Alexander Bell"]}, tr:{q:"Elektrik ampulünü geliştirdiği kabul edilen mucit kimdir?",a:["Thomas Edison","Isaac Newton","Albert Einstein","Alexander Bell"]}, ex:{en:"Thomas Edison is widely credited with developing a practical, long-lasting light bulb in 1879.",tr:"Thomas Edison, 1879'da pratik ve uzun ömürlü bir ampul geliştirmesiyle tanınır."} },
  { id:"tec036", t:"tech", d:3, c:0, en:{q:"What does Wi-Fi allow a device to do?",a:["Connect to the internet wirelessly","Print onto paper","Keep photos forever","Make the screen brighter"]}, tr:{q:"Wi-Fi bir cihazın ne yapmasını sağlar?",a:["İnternete kablosuz bağlanmak","Kâğıda yazdırmak","Fotoğrafları sonsuza dek saklamak","Ekranı parlaklaştırmak"]}, ex:{en:"Wi-Fi lets a device reach the internet using radio waves instead of a physical cable.",tr:"Wi-Fi, bir cihazın fiziksel kablo yerine radyo dalgalarıyla internete ulaşmasını sağlar."} },
  { id:"tec037", t:"tech", d:3, c:0, en:{q:"What are the tiny coloured dots that make up a picture on a screen called?",a:["Pixels","Bytes","Cables","Icons"]}, tr:{q:"Ekrandaki görüntüyü oluşturan küçük renkli noktalara ne denir?",a:["Piksel","Bayt","Kablo","Simge"]}, ex:{en:"Pixels are the tiny coloured squares that combine to form every image a screen displays.",tr:"Pikseller, bir ekranın gösterdiği her görüntüyü oluşturan küçük renkli karelerdir."} },
  { id:"tec038", t:"tech", d:3, c:0, en:{q:"Computers store all their information using only which two digits?",a:["0 and 1","1 and 2","0 and 9","5 and 6"]}, tr:{q:"Bilgisayarlar tüm bilgileri yalnızca hangi iki rakamla saklar?",a:["0 ve 1","1 ve 2","0 ve 9","5 ve 6"]}, ex:{en:"Computers represent everything internally using binary, a system of just two digits, 0 and 1.",tr:"Bilgisayarlar her şeyi içeride sadece 0 ve 1 olmak üzere iki rakamdan oluşan ikili sistemle temsil eder."} },
  { id:"tec039", t:"tech", d:3, c:0, en:{q:"A car's GPS navigator works out where you are using signals from what?",a:["Satellites","Street lamps","Radio songs","Road signs"]}, tr:{q:"Arabadaki GPS cihazı konumunu neyden gelen sinyallerle bulur?",a:["Uydular","Sokak lambaları","Radyo şarkıları","Trafik levhaları"]}, ex:{en:"A GPS receiver calculates your exact location by timing signals from several orbiting satellites.",tr:"GPS alıcısı, konumunu birkaç yörüngedeki uydudan gelen sinyallerin zamanlamasını ölçerek hesaplar."} },
  { id:"tec040", t:"tech", d:3, c:0, en:{q:"What does a 3D printer produce?",a:["Solid objects","Only flat photographs","Sounds","Electricity"]}, tr:{q:"Bir 3D yazıcı ne üretir?",a:["Katı nesneler","Sadece düz fotoğraflar","Sesler","Elektrik"]}, ex:{en:"A 3D printer builds up solid physical objects layer by layer from a digital design.",tr:"3D yazıcı, dijital bir tasarımdan katman katman ekleyerek somut fiziksel nesneler üretir."} },
  { id:"tec041", t:"tech", d:3, c:0, en:{q:"What is a computer virus?",a:["A harmful program","A cracked screen","A kind of cable","A worn-out battery"]}, tr:{q:"Bilgisayar virüsü nedir?",a:["Zararlı bir yazılım","Çatlamış bir ekran","Bir kablo türü","Bitmiş bir pil"]}, ex:{en:"A computer virus is harmful software designed to spread and damage or disrupt a computer.",tr:"Bilgisayar virüsü, yayılıp bir bilgisayara zarar vermek veya onu bozmak üzere tasarlanmış zararlı bir yazılımdır."} },
  { id:"tec042", t:"tech", d:3, c:0, en:{q:"Which brothers made the first successful powered aeroplane flight in 1903?",a:["The Wright brothers","The Montgolfier brothers","The Lumiere brothers","The Grimm brothers"]}, tr:{q:"1903'te ilk başarılı motorlu uçak uçuşunu hangi kardeşler yaptı?",a:["Wright kardeşler","Montgolfier kardeşler","Lumiere kardeşler","Grimm kardeşler"]}, ex:{en:"Orville and Wilbur Wright achieved the first sustained, controlled powered flight in 1903.",tr:"Orville ve Wilbur Wright kardeşler, 1903'te ilk sürdürülebilir ve kontrollü motorlu uçuşu gerçekleştirdi."} },
  { id:"tec043", t:"tech", d:3, c:0, en:{q:"Who built Europe's first printing press using movable metal type?",a:["Johannes Gutenberg","Karl Benz","Galileo Galilei","Leonardo da Vinci"]}, tr:{q:"Avrupa'da hareketli metal harfli ilk matbaayı kim kurdu?",a:["Johannes Gutenberg","Karl Benz","Galileo Galilei","Leonardo da Vinci"]}, ex:{en:"Johannes Gutenberg built Europe's first movable-type printing press around 1440.",tr:"Johannes Gutenberg, Avrupa'nın hareketli harfli ilk matbaasını 1440 civarında kurdu."} },
  { id:"tec044", t:"tech", d:3, c:0, en:{q:"What is a USB memory stick mainly used for?",a:["Storing and carrying files","Cooling the computer","Making the sound louder","Cleaning the screen"]}, tr:{q:"USB bellek çoğunlukla ne için kullanılır?",a:["Dosya saklamak ve taşımak","Bilgisayarı soğutmak","Sesi yükseltmek","Ekranı temizlemek"]}, ex:{en:"A USB stick is a small, portable device used to store and carry digital files.",tr:"USB bellek, dijital dosyaları saklamak ve taşımak için kullanılan küçük ve taşınabilir bir cihazdır."} },
  { id:"tec045", t:"tech", d:3, c:0, en:{q:"What is a drone?",a:["An aircraft with no pilot on board","A type of car engine","A kind of battery","A computer screen"]}, tr:{q:"Drone nedir?",a:["İçinde pilot olmayan hava aracı","Bir araba motoru türü","Bir pil çeşidi","Bir bilgisayar ekranı"]}, ex:{en:"A drone is an aircraft flown remotely or by computer, with no pilot sitting inside it.",tr:"Drone, içinde oturan bir pilot olmadan uzaktan veya bilgisayarla uçurulan bir hava aracıdır."} },
  { id:"tec046", t:"tech", d:3, k:"tf", v:true, en:{q:"Morse code sends messages using short and long signals."}, tr:{q:"Mors alfabesi mesajları kısa ve uzun sinyallerle iletir."}, ex:{en:"Morse code represents letters as patterns of short dots and long dashes.",tr:"Mors alfabesi, harfleri kısa noktalar ve uzun çizgilerden oluşan desenlerle temsil eder."} },
  { id:"tec047", t:"tech", d:3, k:"tf", v:true, en:{q:"The flight recorder called an aeroplane's 'black box' is actually bright orange."}, tr:{q:"Uçaklarda 'kara kutu' denilen kayıt cihazı aslında parlak turuncu renktedir."}, ex:{en:"Flight recorders are painted bright orange, not black, to make them easier to spot in wreckage.",tr:"Uçuş kayıt cihazları, enkazda daha kolay bulunması için siyah değil, parlak turuncu renge boyanır."} },
  { id:"tec048", t:"tech", d:3, k:"tf", v:false, en:{q:"Karl Benz built the world's first petrol-powered car in France."}, tr:{q:"Karl Benz, dünyanın ilk benzinli otomobilini Fransa'da yaptı."}, ex:{en:"Karl Benz built his petrol-powered Motorwagen in Mannheim, Germany, in 1885, not France.",tr:"Karl Benz, benzinli Motorwagen'i 1885'te Fransa'da değil, Almanya'nın Mannheim kentinde inşa etti."} },
  { id:"tec049", t:"tech", d:4, c:0, en:{q:"In computing, what does CPU stand for?",a:["Central Processing Unit","Computer Power Unit","Core Program Utility","Central Program Unit"]}, tr:{q:"Bilişimde CPU neyin kısaltmasıdır?",a:["Merkezî İşlem Birimi","Bilgisayar Güç Birimi","Çekirdek Program Aracı","Merkezî Program Birimi"]}, ex:{en:"CPU stands for Central Processing Unit, the chip that carries out a computer's instructions.",tr:"CPU, bilgisayarın komutlarını yürüten çip olan Merkezî İşlem Birimi'nin kısaltmasıdır."} },
  { id:"tec050", t:"tech", d:4, c:0, en:{q:"Which language is used to style the appearance of a web page?",a:["CSS","HTML","SQL","XML"]}, tr:{q:"Bir web sayfasının görünümünü hangi dil biçimlendirir?",a:["CSS","HTML","SQL","XML"]}, ex:{en:"CSS controls a web page's colours, layout and fonts, while HTML holds its content.",tr:"CSS bir web sayfasının renklerini, düzenini ve yazı tiplerini kontrol eder; HTML ise içeriğini tutar."} },
  { id:"tec051", t:"tech", d:4, c:0, en:{q:"In which year was the first iPhone released?",a:["2007","2005","2009","2010"]}, tr:{q:"İlk iPhone hangi yıl piyasaya çıktı?",a:["2007","2005","2009","2010"]}, ex:{en:"Apple released the first iPhone in 2007, launching the modern smartphone era.",tr:"Apple, ilk iPhone'u 2007'de piyasaya sürerek modern akıllı telefon çağını başlattı."} },
  { id:"tec052", t:"tech", d:4, c:0, en:{q:"Which material are most computer chips made from?",a:["Silicon","Aluminium","Graphite","Limestone"]}, tr:{q:"Bilgisayar çipleri çoğunlukla hangi malzemeden yapılır?",a:["Silisyum","Alüminyum","Grafit","Kireçtaşı"]}, ex:{en:"Silicon is the semiconductor material used to make the microchips inside almost every computer.",tr:"Silikon, neredeyse her bilgisayarın içindeki mikroçiplerin yapımında kullanılan yarı iletken malzemedir."} },
  { id:"tec053", t:"tech", d:4, c:0, en:{q:"Which number system uses only the digits 0 and 1?",a:["Binary","Decimal","Hexadecimal","Roman numerals"]}, tr:{q:"Hangi sayı sistemi yalnızca 0 ve 1 rakamlarını kullanır?",a:["İkili sistem","Onluk sistem","On altılık sistem","Roma rakamları"]}, ex:{en:"Binary represents every number using only the two digits 0 and 1.",tr:"İkili sistem, her sayıyı sadece 0 ve 1 olmak üzere iki rakamla temsil eder."} },
  { id:"tec054", t:"tech", d:4, c:0, en:{q:"Which type of computer storage has no moving parts?",a:["An SSD","A hard disk drive","A DVD drive","A cassette tape"]}, tr:{q:"Hangi bilgisayar depolama türünde hareketli parça yoktur?",a:["SSD","Sabit disk (HDD)","DVD sürücü","Kaset"]}, ex:{en:"An SSD stores data on chips with no spinning disk or moving parts, unlike an older hard drive.",tr:"SSD, eski sabit disklerin aksine, dönen disk veya hareketli parça olmadan verileri çipler üzerinde saklar."} },
  { id:"tec055", t:"tech", d:4, c:0, en:{q:"Who is often called the world's first computer programmer?",a:["Ada Lovelace","Marie Curie","Rosalind Franklin","Amelia Earhart"]}, tr:{q:"Dünyanın ilk bilgisayar programcısı olarak kim anılır?",a:["Ada Lovelace","Marie Curie","Rosalind Franklin","Amelia Earhart"]}, ex:{en:"Ada Lovelace wrote an algorithm for an early mechanical computer in the 1840s, decades before computers existed.",tr:"Ada Lovelace, bilgisayarlar var olmadan onlarca yıl önce, 1840'larda erken bir mekanik bilgisayar için bir algoritma yazdı."} },
  { id:"tec056", t:"tech", d:4, c:0, en:{q:"In a digital image, what is a pixel?",a:["One tiny dot of the picture","A type of camera lens","An image file format","The frame around a photo"]}, tr:{q:"Dijital bir görüntüde piksel nedir?",a:["Görüntünün küçücük bir noktası","Bir kamera lensi türü","Bir resim dosyası biçimi","Fotoğrafın etrafındaki çerçeve"]}, ex:{en:"A pixel is the smallest single point of colour that combines with millions of others to form an image.",tr:"Piksel, bir görüntüyü oluşturmak için milyonlarcasıyla birleşen en küçük tek renk noktasıdır."} },
  { id:"tec057", t:"tech", d:4, c:0, en:{q:"When files are stored in the cloud, where are they really kept?",a:["On remote servers in data centres","In the device's own memory","On the phone's SIM card","Inside the Wi-Fi router"]}, tr:{q:"Dosyalar bulutta saklandığında aslında nerede tutulur?",a:["Veri merkezlerindeki uzak sunucularda","Cihazın kendi belleğinde","Telefonun SIM kartında","Wi-Fi modemin içinde"]}, ex:{en:"\"The cloud\" is really just other people's computers, storing your files on servers inside data centres.",tr:"\"Bulut\" aslında başkalarının bilgisayarlarıdır; dosyaların, veri merkezlerindeki sunucularda saklanır."} },
  { id:"tec058", t:"tech", d:4, c:0, en:{q:"Johannes Gutenberg is famous for developing what in the 1400s?",a:["The printing press","The telescope","The steam engine","The magnetic compass"]}, tr:{q:"Johannes Gutenberg 1400'lerde neyi geliştirmesiyle ünlüdür?",a:["Matbaa","Teleskop","Buhar makinesi","Pusula"]}, ex:{en:"Gutenberg's movable-type press, from around 1440, made printing books far faster than copying by hand.",tr:"Gutenberg'in 1440 civarındaki hareketli harfli matbaası, kitap basmayı elle kopyalamaktan çok daha hızlı hâle getirdi."} },
  { id:"tec059", t:"tech", d:4, c:0, en:{q:"What is Bluetooth mainly used for?",a:["Linking nearby devices wirelessly","Charging a battery faster","Cooling the processor","Storing files permanently"]}, tr:{q:"Bluetooth esas olarak ne için kullanılır?",a:["Yakındaki cihazları kablosuz bağlamak","Pili daha hızlı şarj etmek","İşlemciyi soğutmak","Dosyaları kalıcı olarak saklamak"]}, ex:{en:"Bluetooth uses short-range radio waves to connect nearby devices, like a phone and headphones, without wires.",tr:"Bluetooth, telefon ve kulaklık gibi yakındaki cihazları kablosuz bağlamak için kısa menzilli radyo dalgaları kullanır."} },
  { id:"tec060", t:"tech", d:4, c:0, en:{q:"On a computer network, what does a firewall mainly do?",a:["Blocks unwanted network traffic","Puts out electrical fires","Makes the screen brighter","Stores passwords safely"]}, tr:{q:"Bilgisayar ağında güvenlik duvarı esas olarak ne yapar?",a:["İstenmeyen ağ trafiğini engeller","Elektrik yangınlarını söndürür","Ekranı daha parlak yapar","Şifreleri güvenle saklar"]}, ex:{en:"A firewall inspects network traffic and blocks connections it judges unsafe or unwanted.",tr:"Güvenlik duvarı, ağ trafiğini denetler ve güvensiz veya istenmeyen bulduğu bağlantıları engeller."} },
  { id:"tec061", t:"tech", d:4, k:"tf", v:true, en:{q:"The QR code was invented in Japan, where it was first used to track car parts."}, tr:{q:"QR kod Japonya'da icat edildi ve ilk olarak otomobil parçalarını takip etmekte kullanıldı."}, ex:{en:"Denso Wave engineers in Japan invented the QR code in 1994 to track parts on car assembly lines.",tr:"Japonya'daki Denso Wave mühendisleri, araba montaj hatlarındaki parçaları takip etmek için 1994'te QR kodunu icat etti."} },
  { id:"tec062", t:"tech", d:4, k:"tf", v:true, en:{q:"Most internet data sent between continents travels through cables lying on the ocean floor."}, tr:{q:"Kıtalar arasında gönderilen internet verisinin çoğu, okyanus tabanına döşenmiş kablolarla taşınır."}, ex:{en:"Long undersea fibre-optic cables, not satellites, carry the vast majority of international internet traffic.",tr:"Uluslararası internet trafiğinin büyük çoğunluğunu uydular değil, denizin altındaki uzun fiber optik kablolar taşır."} },
  { id:"tec063", t:"tech", d:4, k:"tf", v:false, en:{q:"Scratch, the block-based coding language for beginners, was created at Stanford University."}, tr:{q:"Yeni başlayanlar için blok tabanlı kodlama dili Scratch, Stanford Üniversitesi'nde geliştirildi."}, ex:{en:"Scratch was created at MIT's Media Lab to teach children the basics of coding through blocks.",tr:"Scratch, çocuklara blok tabanlı kodlamanın temellerini öğretmek için MIT Medya Laboratuvarı'nda geliştirildi."} },
  { id:"tec064", t:"tech", d:4, k:"tf", v:true, en:{q:"The first computer mouse, built in the 1960s, had a case made of wood."}, tr:{q:"1960'larda yapılan ilk bilgisayar faresinin gövdesi tahtadandı."}, ex:{en:"Douglas Engelbart's first computer mouse prototype, from 1964, was housed in a simple wooden shell.",tr:"Douglas Engelbart'ın 1964'teki ilk bilgisayar faresi prototipi, basit bir tahta kabuk içindeydi."} },
  { id:"tec065", t:"tech", d:4, k:"tf", v:false, en:{q:"A computer's RAM keeps everything stored in it when the computer is switched off."}, tr:{q:"Bir bilgisayarın RAM belleği, bilgisayar kapatıldığında içindeki her şeyi saklamaya devam eder."}, ex:{en:"RAM is volatile memory: everything it holds disappears the instant the power is switched off.",tr:"RAM geçici bir bellektir: güç kesildiği anda içinde tuttuğu her şey kaybolur."} },
  { id:"tec066", t:"tech", d:5, c:0, en:{q:"In computing, what does RAM stand for?",a:["Random Access Memory","Rapid Access Module","Read Access Memory","Runtime Allocated Memory"]}, tr:{q:"Bilişimde RAM neyin kısaltmasıdır?",a:["Rastgele Erişimli Bellek","Hızlı Erişim Modülü","Okuma Erişim Belleği","Çalışma Zamanı Belleği"]}, ex:{en:"RAM, Random Access Memory, temporarily holds data a computer is actively using.",tr:"RAM, yani rastgele erişimli bellek, bilgisayarın o an aktif olarak kullandığı verileri geçici olarak tutar."} },
  { id:"tec067", t:"tech", d:5, c:0, en:{q:"Who invented the World Wide Web?",a:["Tim Berners-Lee","Vint Cerf","Bill Gates","Alan Turing"]}, tr:{q:"World Wide Web'i kim icat etti?",a:["Tim Berners-Lee","Vint Cerf","Bill Gates","Alan Turing"]}, ex:{en:"Tim Berners-Lee invented the World Wide Web in 1989 while working at CERN.",tr:"Tim Berners-Lee, CERN'de çalışırken 1989'da World Wide Web'i icat etti."} },
  { id:"tec068", t:"tech", d:5, c:0, en:{q:"Which programming language was created by Guido van Rossum?",a:["Python","Ruby","Perl","Java"]}, tr:{q:"Guido van Rossum hangi programlama dilini yarattı?",a:["Python","Ruby","Perl","Java"]}, ex:{en:"Guido van Rossum began developing Python in the late 1980s, releasing it in 1991.",tr:"Guido van Rossum, Python'u 1980'lerin sonunda geliştirmeye başladı ve 1991'de yayımladı."} },
  { id:"tec069", t:"tech", d:5, c:0, en:{q:"What is the binary number 1010 equal to in decimal?",a:["10","8","12","5"]}, tr:{q:"İkilik sistemdeki 1010 sayısı onluk sistemde kaçtır?",a:["10","8","12","5"]}, ex:{en:"Reading right to left, 1010 in binary is 8+0+2+0, which equals 10 in decimal.",tr:"Sağdan sola okunduğunda ikili sistemdeki 1010, 8+0+2+0 olup ondalık sistemde 10'a eşittir."} },
  { id:"tec070", t:"tech", d:5, c:0, en:{q:"Which of these units represents the largest amount of data?",a:["A terabyte","A gigabyte","A megabyte","A kilobyte"]}, tr:{q:"Bu birimlerden hangisi en büyük veri miktarını ifade eder?",a:["Terabayt","Gigabayt","Megabayt","Kilobayt"]}, ex:{en:"A terabyte holds about a thousand gigabytes, making it far larger than a megabyte or kilobyte.",tr:"Bir terabayt yaklaşık bin gigabayta karşılık gelir, bu da onu bir megabayt ya da kilobayttan çok daha büyük yapar."} },
  { id:"tec071", t:"tech", d:5, c:0, en:{q:"Which computer part is mainly used to create the images shown on the screen?",a:["The graphics card","The hard drive","The power supply","The network card"]}, tr:{q:"Ekranda görünen görüntüleri oluşturmakla esas olarak hangi parça ilgilenir?",a:["Ekran kartı","Sabit disk","Güç kaynağı","Ağ kartı"]}, ex:{en:"The graphics card processes and renders the visuals shown on a computer's display.",tr:"Ekran kartı, bir bilgisayarın ekranında gösterilen görselleri işler ve oluşturur."} },
  { id:"tec072", t:"tech", d:5, c:0, en:{q:"What is a program that turns source code into machine code called?",a:["A compiler","A browser","A spreadsheet","A driver"]}, tr:{q:"Kaynak kodu makine koduna çeviren programa ne denir?",a:["Derleyici","Tarayıcı","Hesap tablosu","Sürücü yazılımı"]}, ex:{en:"A compiler translates human-written source code into machine code a computer's processor can run.",tr:"Derleyici, insan tarafından yazılan kaynak kodu bilgisayarın işlemcisinin çalıştırabileceği makine koduna çevirir."} },
  { id:"tec073", t:"tech", d:5, c:0, en:{q:"What is the main job of a firewall on a computer network?",a:["Blocking unwanted network traffic","Cooling the processor","Backing up photos","Charging the battery"]}, tr:{q:"Bir bilgisayar ağında güvenlik duvarının temel görevi nedir?",a:["İstenmeyen ağ trafiğini engellemek","İşlemciyi soğutmak","Fotoğrafları yedeklemek","Pili şarj etmek"]}, ex:{en:"A firewall's core job is filtering network traffic to block connections that look unsafe.",tr:"Güvenlik duvarının temel görevi, güvensiz görünen bağlantıları engellemek için ağ trafiğini filtrelemektir."} },
  { id:"tec074", t:"tech", d:5, c:0, en:{q:"What was the name of the first artificial satellite put into orbit, launched in 1957?",a:["Sputnik 1","Explorer 1","Apollo 1","Vostok 1"]}, tr:{q:"1957'de yörüngeye gönderilen ilk yapay uydunun adı neydi?",a:["Sputnik 1","Explorer 1","Apollo 1","Vostok 1"]}, ex:{en:"The Soviet Union launched Sputnik 1 in October 1957, the first satellite to orbit Earth.",tr:"Sovyetler Birliği, Dünya'nın yörüngesine giren ilk uydu olan Sputnik 1'i Ekim 1957'de fırlattı."} },
  { id:"tec075", t:"tech", d:5, c:0, en:{q:"Which file format is normally used to compress several files into one archive?",a:["ZIP","JPG","MP3","TXT"]}, tr:{q:"Birden çok dosyayı tek bir arşivde sıkıştırmak için genellikle hangi dosya biçimi kullanılır?",a:["ZIP","JPG","MP3","TXT"]}, ex:{en:"The ZIP format bundles multiple files together and shrinks them to save storage space.",tr:"ZIP formatı, birden fazla dosyayı bir araya toplayıp yer kazanmak için sıkıştırır."} },
  { id:"tec076", t:"tech", d:5, c:0, en:{q:"Marmaray in Istanbul is a railway running through a tunnel under what?",a:["The Bosphorus","The Dardanelles","The Danube","Lake Van"]}, tr:{q:"İstanbul'daki Marmaray, hangisinin altındaki tünelden geçen bir demiryolu hattıdır?",a:["İstanbul Boğazı","Çanakkale Boğazı","Tuna Nehri","Van Gölü"]}, ex:{en:"Marmaray runs through an undersea tunnel beneath the Bosphorus, linking Istanbul's European and Asian sides by rail.",tr:"Marmaray, İstanbul'un Avrupa ve Asya yakasını demiryoluyla birleştiren, Boğaz'ın altındaki bir deniz altı tünelinden geçer."} },
  { id:"tec077", t:"tech", d:5, k:"tf", v:false, en:{q:"In the mobile network name 5G, the letter G stands for \"gigabyte\"."}, tr:{q:"Mobil ağ adı 5G'deki G harfi \"gigabayt\" anlamına gelir."}, ex:{en:"In 5G, the G stands for \"Generation\", marking it as the fifth generation of mobile networks.",tr:"5G'deki G, mobil ağların beşinci nesli anlamına gelen \"Generation\" (nesil) kelimesinin baş harfidir."} },
  { id:"tec078", t:"tech", d:5, k:"tf", v:true, en:{q:"The Linux kernel was created in 1991 by Linus Torvalds, then a student in Finland."}, tr:{q:"Linux çekirdeği 1991'de, o sırada Finlandiya'da öğrenci olan Linus Torvalds tarafından yazıldı."}, ex:{en:"Linus Torvalds, then a Finnish computer science student, released the first Linux kernel in 1991.",tr:"O sırada Finlandiyalı bir bilgisayar bilimi öğrencisi olan Linus Torvalds, ilk Linux çekirdeğini 1991'de yayımladı."} },
  { id:"tec079", t:"tech", d:5, k:"tf", v:false, en:{q:"The computer mouse was invented by engineers at Apple in the 1980s."}, tr:{q:"Bilgisayar faresi 1980'lerde Apple'daki mühendisler tarafından icat edildi."}, ex:{en:"Douglas Engelbart and his team at SRI invented the computer mouse in the 1960s, long before Apple existed.",tr:"Bilgisayar faresini, Apple henüz yokken 1960'larda Douglas Engelbart ve SRI'daki ekibi icat etti."} },
  { id:"tec080", t:"tech", d:5, k:"tf", v:true, en:{q:"Fibre-optic cables carry data as pulses of light through thin strands of glass."}, tr:{q:"Fiber optik kablolar veriyi ince cam lifler içinde ışık darbeleri hâlinde taşır."}, ex:{en:"Fibre-optic cables send data as flashes of light bouncing along thin strands of glass.",tr:"Fiber optik kablolar, veriyi ince cam liflerin içinde sekerek ilerleyen ışık titreşimleri olarak gönderir."} },
  { id:"tec081", t:"tech", d:5, k:"tf", v:false, en:{q:"The first digital camera was built by an engineer at Sony in 1975."}, tr:{q:"İlk dijital fotoğraf makinesi 1975'te Sony'de bir mühendis tarafından yapıldı."}, ex:{en:"Steven Sasson, an engineer at Kodak, built the first digital camera in 1975, not at Sony.",tr:"İlk dijital fotoğraf makinesini, Sony'de değil, Kodak'ta mühendis olan Steven Sasson 1975'te yaptı."} },
  { id:"tec082", t:"tech", d:5, k:"tf", v:true, en:{q:"Java and JavaScript are two separate programming languages, not two versions of one language."}, tr:{q:"Java ve JavaScript, aynı dilin iki sürümü değil, birbirinden ayrı iki programlama dilidir."}, ex:{en:"Despite the similar name, Java and JavaScript are unrelated languages with different designs and uses.",tr:"Benzer isimlere rağmen Java ve JavaScript, farklı tasarım ve kullanımlara sahip birbiriyle ilgisiz dillerdir."} },
  { id:"tec083", t:"tech", d:6, c:0, en:{q:"In computing, what does HTTP stand for?",a:["HyperText Transfer Protocol","High Transfer Text Protocol","Hyperlink Text Transport Path","Host Transfer Type Protocol"]}, tr:{q:"HTTP neyin kısaltmasıdır?",a:["HyperText Transfer Protocol","High Transfer Text Protocol","Hyperlink Text Transport Path","Host Transfer Type Protocol"]} },
  { id:"tec084", t:"tech", d:6, c:0, en:{q:"How many bits are there in one byte?",a:["Eight","Four","Sixteen","Ten"]}, tr:{q:"Bir bayt kaç bittir?",a:["Sekiz","Dört","On altı","On"]} },
  { id:"tec085", t:"tech", d:6, c:0, en:{q:"Which mathematician devised the test of machine intelligence now named after him?",a:["Alan Turing","John von Neumann","Claude Shannon","Kurt Gödel"]}, tr:{q:"Makine zekâsı testine adını veren matematikçi kimdir?",a:["Alan Turing","John von Neumann","Claude Shannon","Kurt Gödel"]} },
  { id:"tec086", t:"tech", d:6, c:0, en:{q:"Who co-founded Microsoft with Bill Gates in 1975?",a:["Paul Allen","Steve Ballmer","Steve Wozniak","Gordon Moore"]}, tr:{q:"1975'te Microsoft'u Bill Gates ile birlikte kim kurdu?",a:["Paul Allen","Steve Ballmer","Steve Wozniak","Gordon Moore"]} },
  { id:"tec087", t:"tech", d:6, c:0, en:{q:"Which system turns a website's name into the numeric address computers use?",a:["DNS","FTP","SMTP","VPN"]}, tr:{q:"Bir web sitesinin adını bilgisayarların kullandığı sayısal adrese hangi sistem çevirir?",a:["DNS","FTP","SMTP","VPN"]} },
  { id:"tec088", t:"tech", d:6, c:0, en:{q:"Which network, funded by the US military, was the direct ancestor of the internet?",a:["ARPANET","Ethernet","Usenet","Telnet"]}, tr:{q:"ABD ordusunun finanse ettiği hangi ağ, internetin doğrudan atasıdır?",a:["ARPANET","Ethernet","Usenet","Telnet"]} },
  { id:"tec089", t:"tech", d:6, c:0, en:{q:"Which image format uses lossy compression, throwing away detail to shrink photos?",a:["JPEG","PNG","SVG","BMP"]}, tr:{q:"Hangi görüntü biçimi, fotoğrafları küçültmek için ayrıntı atan kayıplı sıkıştırma kullanır?",a:["JPEG","PNG","SVG","BMP"]} },
  { id:"tec090", t:"tech", d:6, c:0, en:{q:"Which 19th-century figure is regarded as the first computer programmer?",a:["Ada Lovelace","Grace Hopper","Hedy Lamarr","Marie Curie"]}, tr:{q:"19. yüzyılda yaşamış, ilk bilgisayar programcısı sayılan kişi kimdir?",a:["Ada Lovelace","Grace Hopper","Hedy Lamarr","Marie Curie"]} },
  { id:"tec091", t:"tech", d:6, c:0, en:{q:"Moore's Law describes the steady doubling of what?",a:["Transistors on a chip","Internet users worldwide","Screen pixel density","Hard-drive spin speed"]}, tr:{q:"Moore Yasası neyin düzenli olarak ikiye katlanmasını anlatır?",a:["Çipteki transistör sayısı","Dünyadaki internet kullanıcıları","Ekran piksel yoğunluğu","Sabit disk dönüş hızı"]} },
  { id:"tec092", t:"tech", d:6, c:0, en:{q:"Which of these storage devices has no moving parts?",a:["Solid-state drive (SSD)","Hard disk drive (HDD)","Floppy disk","DVD drive"]}, tr:{q:"Bu depolama aygıtlarından hangisinde hareketli parça yoktur?",a:["Katı hâl sürücüsü (SSD)","Sabit disk (HDD)","Disket","DVD sürücü"]} },
  { id:"tec093", t:"tech", d:6, c:0, en:{q:"The GPS satellite navigation system is owned and operated by which country?",a:["The United States","Russia","China","Japan"]}, tr:{q:"GPS uydu navigasyon sistemi hangi ülke tarafından işletilir?",a:["ABD","Rusya","Çin","Japonya"]} },
  { id:"tec094", t:"tech", d:6, c:0, en:{q:"Bluetooth technology is named after a medieval king of which country?",a:["Denmark","Sweden","Germany","Scotland"]}, tr:{q:"Bluetooth teknolojisi hangi ülkenin ortaçağdaki kralından adını alır?",a:["Danimarka","İsveç","Almanya","İskoçya"]} },
  { id:"tec095", t:"tech", d:6, c:0, en:{q:"The QWERTY layout was originally designed for which machine?",a:["The typewriter","The telegraph","The printing press","The cash register"]}, tr:{q:"QWERTY düzeni ilk olarak hangi makine için tasarlandı?",a:["Daktilo","Telgraf","Matbaa","Yazar kasa"]} },
  { id:"tec096", t:"tech", d:6, k:"tf", v:false, en:{q:"HTML is a programming language."}, tr:{q:"HTML bir programlama dilidir."} },
  { id:"tec097", t:"tech", d:6, k:"tf", v:true, en:{q:"The QR code was invented in Japan in the 1990s."}, tr:{q:"QR kod, 1990'larda Japonya'da icat edildi."} },
  { id:"tec098", t:"tech", d:6, k:"tf", v:false, en:{q:"The Concorde supersonic airliner was jointly developed by Britain and Germany."}, tr:{q:"Süpersonik yolcu uçağı Concorde, İngiltere ve Almanya tarafından ortaklaşa geliştirildi."} },
  { id:"tec099", t:"tech", d:6, k:"tf", v:true, en:{q:"Charles Babbage designed a mechanical general-purpose computer called the Analytical Engine."}, tr:{q:"Charles Babbage, Analitik Makine adında mekanik ve genel amaçlı bir bilgisayar tasarladı."} },
  { id:"tec100", t:"tech", d:6, k:"tf", v:false, en:{q:"The computer mouse was invented at IBM in the 1960s."}, tr:{q:"Bilgisayar faresi, 1960'larda IBM'de icat edildi."} },
  { id:"tec101", t:"tech", d:6, k:"tf", v:false, en:{q:"On the web, the error code 404 means that the server is overloaded."}, tr:{q:"İnternette 404 hata kodu, sunucunun aşırı yüklendiği anlamına gelir."} },
  { id:"tec102", t:"tech", d:7, c:0, en:{q:"What is the default port for HTTPS traffic?",a:["443","80","22","8080"]}, tr:{q:"HTTPS trafiğinin varsayılan portu hangisidir?",a:["443","80","22","8080"]} },
  { id:"tec103", t:"tech", d:7, c:0, en:{q:"Which data structure works on a last-in, first-out basis?",a:["A stack","A queue","A linked list","A hash table"]}, tr:{q:"Hangi veri yapısı son giren ilk çıkar mantığıyla çalışır?",a:["Yığın (stack)","Kuyruk (queue)","Bağlı liste","Karma tablo"]} },
  { id:"tec104", t:"tech", d:7, c:0, en:{q:"Unix time counts the seconds elapsed since the start of which year?",a:["1970","1900","1980","1960"]}, tr:{q:"Unix zamanı, hangi yılın başından itibaren geçen saniyeleri sayar?",a:["1970","1900","1980","1960"]} },
  { id:"tec105", t:"tech", d:7, c:0, en:{q:"Launched in 2011, which was the first Earth observation satellite designed and built in Turkey?",a:["RASAT","BİLSAT-1","GÖKTÜRK-2","Türksat 3A"]}, tr:{q:"2011'de fırlatılan, Türkiye'de tasarlanıp üretilen ilk yer gözlem uydusu hangisidir?",a:["RASAT","BİLSAT-1","GÖKTÜRK-2","Türksat 3A"]} },
  { id:"tec106", t:"tech", d:7, c:0, en:{q:"Who made the world's first call from a handheld mobile phone, in 1973?",a:["Martin Cooper","Ray Tomlinson","Douglas Engelbart","Jack Kilby"]}, tr:{q:"1973'te el tipi bir cep telefonundan dünyanın ilk aramasını kim yaptı?",a:["Martin Cooper","Ray Tomlinson","Douglas Engelbart","Jack Kilby"]} },
  { id:"tec107", t:"tech", d:7, c:0, en:{q:"Which language, created in 1960s Norway, introduced classes and objects to programming?",a:["Simula","Smalltalk","Lisp","Pascal"]}, tr:{q:"1960'larda Norveç'te geliştirilen, programlamaya sınıf ve nesne kavramlarını kazandıran dil hangisidir?",a:["Simula","Smalltalk","Lisp","Pascal"]} },
  { id:"tec108", t:"tech", d:7, c:0, en:{q:"Which aircraft, entering service in 1952, was the world's first commercial jet airliner?",a:["De Havilland Comet","Boeing 707","Tupolev Tu-104","Sud Aviation Caravelle"]}, tr:{q:"1952'de hizmete giren, dünyanın ilk ticari jet yolcu uçağı hangisiydi?",a:["De Havilland Comet","Boeing 707","Tupolev Tu-104","Sud Aviation Caravelle"]} },
  { id:"tec109", t:"tech", d:7, c:0, en:{q:"In databases, which property means a transaction either fully completes or has no effect?",a:["Atomicity","Durability","Isolation","Consistency"]}, tr:{q:"Veritabanlarında bir işlemin ya tümüyle tamamlanmasını ya da hiç etki etmemesini sağlayan özellik hangisidir?",a:["Atomiklik","Kalıcılık","Yalıtım","Tutarlılık"]} },
  { id:"tec110", t:"tech", d:7, c:0, en:{q:"In 1969, the first ARPANET message was sent from UCLA to which institution?",a:["Stanford Research Institute","MIT","Harvard University","University of Utah"]}, tr:{q:"1969'da ilk ARPANET mesajı UCLA'dan hangi kuruma gönderildi?",a:["Stanford Araştırma Enstitüsü","MIT","Harvard Üniversitesi","Utah Üniversitesi"]} },
  { id:"tec111", t:"tech", d:7, c:0, en:{q:"Who led the team that developed the on-board flight software for the Apollo missions?",a:["Margaret Hamilton","Grace Hopper","Katherine Johnson","Hedy Lamarr"]}, tr:{q:"Apollo görevlerinin uçuş yazılımını geliştiren ekibe kim liderlik etti?",a:["Margaret Hamilton","Grace Hopper","Katherine Johnson","Hedy Lamarr"]} },
  { id:"tec112", t:"tech", d:7, c:0, en:{q:"The Alto, an early computer with a graphical desktop, was developed at which company?",a:["Xerox","IBM","Hewlett-Packard","Digital Equipment Corp"]}, tr:{q:"Grafik masaüstüne sahip erken dönem bilgisayar Alto hangi şirkette geliştirildi?",a:["Xerox","IBM","Hewlett-Packard","Digital Equipment Corp"]} },
  { id:"tec113", t:"tech", d:7, c:0, en:{q:"In which year did Intel release the 4004, the first commercially sold microprocessor?",a:["1971","1965","1977","1983"]}, tr:{q:"Intel, ticari olarak satılan ilk mikroişlemci olan 4004'ü hangi yıl piyasaya sürdü?",a:["1971","1965","1977","1983"]} },
  { id:"tec114", t:"tech", d:7, k:"tf", v:false, en:{q:"The Colossus computers at Bletchley Park were built to break the German Enigma cipher."}, tr:{q:"Bletchley Park'taki Colossus bilgisayarları Alman Enigma şifresini kırmak için yapılmıştı."} },
  { id:"tec115", t:"tech", d:7, k:"tf", v:false, en:{q:"JavaScript was created at Sun Microsystems as a lightweight companion to the Java language."}, tr:{q:"JavaScript, Java dilinin hafif bir tamamlayıcısı olarak Sun Microsystems'te geliştirildi."} },
  { id:"tec116", t:"tech", d:7, k:"tf", v:false, en:{q:"Wi-Fi wireless networking is defined by the IEEE 802.3 family of standards."}, tr:{q:"Wi-Fi kablosuz ağ teknolojisi IEEE 802.3 standartlar ailesiyle tanımlanır."} },
  { id:"tec117", t:"tech", d:7, k:"tf", v:true, en:{q:"The world's first webcam was set up at Cambridge University to watch a coffee pot."}, tr:{q:"Dünyanın ilk web kamerası, bir kahve makinesini izlemek için Cambridge Üniversitesi'nde kuruldu."} },
  { id:"tec118", t:"tech", d:8, c:0, en:{q:"What is the average time complexity of binary search?",a:["O(log n)","O(n)","O(n log n)","O(1)"]}, tr:{q:"İkili aramanın ortalama zaman karmaşıklığı nedir?",a:["O(log n)","O(n)","O(n log n)","O(1)"]} },
  { id:"tec119", t:"tech", d:8, c:0, en:{q:"In public-key cryptography, which key is used to encrypt a message to someone?",a:["Their public key","Their private key","Your private key","A shared salt"]}, tr:{q:"Açık anahtarlı şifrelemede birine gönderilecek mesaj hangi anahtarla şifrelenir?",a:["Onun açık anahtarı","Onun özel anahtarı","Senin özel anahtarın","Ortak bir tuz değeri"]} },
  { id:"tec120", t:"tech", d:8, c:0, en:{q:"In the modern UTF-8 standard, what is the maximum number of bytes used for one character?",a:["Four","Two","Six","Eight"]}, tr:{q:"Güncel UTF-8 standardında bir karakter en fazla kaç bayt ile kodlanır?",a:["Dört","İki","Altı","Sekiz"]} },
  { id:"tec121", t:"tech", d:8, c:0, en:{q:"In IEEE 754 double precision, how many bits are used for the exponent field?",a:["11 bits","8 bits","12 bits","16 bits"]}, tr:{q:"IEEE 754 çift duyarlıklı sayı biçiminde üs (exponent) alanı kaç bittir?",a:["11 bit","8 bit","12 bit","16 bit"]} },
  { id:"tec122", t:"tech", d:8, c:0, en:{q:"Which protocol exchanges routing information between autonomous systems on the internet?",a:["BGP","OSPF","RIP","ICMP"]}, tr:{q:"İnternette otonom sistemler arasında yönlendirme bilgisini hangi protokol taşır?",a:["BGP","OSPF","RIP","ICMP"]} },
  { id:"tec123", t:"tech", d:8, c:0, en:{q:"What mainly distinguishes Harvard architecture from von Neumann architecture?",a:["Separate instruction and data memory","A larger register file","The absence of any cache","Use of binary arithmetic"]}, tr:{q:"Harvard mimarisini von Neumann mimarisinden ayıran temel özellik nedir?",a:["Komut ve veri belleklerinin ayrı olması","Daha büyük yazmaç dosyası","Hiç önbellek bulunmaması","İkilik aritmetik kullanması"]} },
  { id:"tec124", t:"tech", d:8, c:0, en:{q:"Which database normal form requires every determinant to be a candidate key?",a:["Boyce-Codd normal form","Second normal form","Third normal form","Fourth normal form"]}, tr:{q:"Her belirleyicinin bir aday anahtar olmasını şart koşan normal form hangisidir?",a:["Boyce-Codd normal formu","İkinci normal form","Üçüncü normal form","Dördüncü normal form"]} },
  { id:"tec125", t:"tech", d:8, c:0, en:{q:"What is the block size of AES, no matter which key length is chosen?",a:["128 bits","64 bits","192 bits","256 bits"]}, tr:{q:"Anahtar uzunluğu ne olursa olsun AES'in blok boyutu kaç bittir?",a:["128 bit","64 bit","192 bit","256 bit"]} },
  { id:"tec126", t:"tech", d:8, c:0, en:{q:"Which computer was the first to run a program stored in its own memory, in 1948?",a:["The Manchester Baby","ENIAC","Colossus","EDSAC"]}, tr:{q:"1948'de kendi belleğinde saklanan bir programı çalıştıran ilk bilgisayar hangisidir?",a:["Manchester Baby","ENIAC","Colossus","EDSAC"]} },
  { id:"tec127", t:"tech", d:8, c:0, en:{q:"Which programming language first introduced automatic garbage collection?",a:["Lisp","Smalltalk","Algol 60","Java"]}, tr:{q:"Otomatik çöp toplamayı (garbage collection) ilk kez hangi programlama dili getirdi?",a:["Lisp","Smalltalk","Algol 60","Java"]} },
  { id:"tec128", t:"tech", d:8, c:0, en:{q:"Which was the first Turkish communications satellite successfully placed in orbit?",a:["Türksat 1B","Türksat 1A","Türksat 2A","Göktürk-1"]}, tr:{q:"Yörüngeye başarıyla yerleştirilen ilk Türk haberleşme uydusu hangisidir?",a:["Türksat 1B","Türksat 1A","Türksat 2A","Göktürk-1"]} },
  { id:"tec129", t:"tech", d:8, k:"tf", v:false, en:{q:"Because of relativity, atomic clocks on GPS satellites tick more slowly than clocks on the ground."}, tr:{q:"Görelilik nedeniyle GPS uydularındaki atomik saatler, yerdeki saatlerden daha yavaş çalışır."} },
  { id:"tec130", t:"tech", d:8, k:"tf", v:true, en:{q:"The Panama Canal lifts ships through locks, but the Suez Canal has no locks at all."}, tr:{q:"Panama Kanalı gemileri kilit havuzlarıyla yükseltir, ama Süveyş Kanalı'nda hiç kilit havuzu yoktur."} },
  { id:"tec131", t:"tech", d:8, k:"tf", v:true, en:{q:"The term 'artificial intelligence' was coined for a 1956 research workshop at Dartmouth College."}, tr:{q:"'Yapay zekâ' terimi, 1956'da Dartmouth College'daki bir araştırma çalıştayı için ortaya atıldı."} },
  { id:"tec132", t:"tech", d:8, k:"tf", v:false, en:{q:"In the seven-layer OSI model, the network layer sits directly above the transport layer."}, tr:{q:"Yedi katmanlı OSI modelinde ağ katmanı, doğrudan taşıma katmanının üstünde yer alır."} }
);
